/** Arguments of `browser.call(name, …)`: optional when the command has no required argument. */
export type CallArgs<N extends CommandName> = {} extends CommandArgs<N>
  ? [args?: CommandArgs<N>, options?: CallOptions]
  : [args: CommandArgs<N>, options?: CallOptions];

/** Every command as `browser.<group>.<action>(args, options?)`. Built by {@link createBrowser}. */
export interface Browser {
  /** Call a command by its dotted name: `browser.call("tabs.list")`. */
  call<N extends CommandName>(name: N, ...args: CallArgs<N>): Promise<CommandOutput<N>>;
  /** Commands `input.*`. */
  input: {
    /**
     * Press keys or shortcuts on the focused element ("Enter", "Control+A", "Tab Tab Enter"). To type text into a field use page_act fill/type.
     *
     * `input.keys` (MCP: `input_keys`): toolset `core`, act, mutates the tab.
     */
    keys(args: InputKeysArgs, options?: CallOptions): Promise<InputKeysOutput>;
  };
  /** Commands `nav.*`. */
  nav: {
    /**
     * Go back one page in the tab's history and wait for it to load. Old refs become stale: take a new page_snapshot.
     *
     * `nav.back` (MCP: `nav_back`): toolset `core`, act, mutates the tab.
     */
    back(args?: NavBackArgs, options?: CallOptions): Promise<NavBackOutput>;
    /**
     * Go forward one page in the tab's history and wait for it to load.
     *
     * `nav.forward` (MCP: `nav_forward`): toolset `core`, act, mutates the tab.
     */
    forward(args?: NavForwardArgs, options?: CallOptions): Promise<NavForwardOutput>;
    /**
     * Navigate a tab to a URL and wait until the page has loaded. Returns the tab's final url and title.
     *
     * `nav.goto` (MCP: `nav_goto`): toolset `core`, act, mutates the tab.
     */
    goto(args: NavGotoArgs, options?: CallOptions): Promise<NavGotoOutput>;
    /**
     * Reload the page and wait for it to load. Old refs become stale.
     *
     * `nav.reload` (MCP: `nav_reload`): toolset `core`, act, mutates the tab.
     */
    reload(args?: NavReloadArgs, options?: CallOptions): Promise<NavReloadOutput>;
    /**
     * Wait until the page has loaded, a text appears, an element (ref) is visible, or the URL contains a value. TIMEOUT if it does not happen in time.
     *
     * `nav.wait` (MCP: `nav_wait`): toolset `core`, read.
     */
    wait(args: NavWaitArgs, options?: CallOptions): Promise<NavWaitOutput>;
  };
  /** Commands `page.*`. */
  page: {
    /**
     * Act on an element by ref: click, dblclick, fill, type, select, check, uncheck, hover, press, scroll, focus. Checks the element is visible, enabled and not covered (else NOT_INTERACTABLE naming what is in the way), uses real input events, waits for the page, and returns a one-line diff of what changed.
     *
     * `page.act` (MCP: `page_act`): toolset `core`, act, mutates the tab.
     */
    act(args: PageActArgs, options?: CallOptions): Promise<PageActOutput>;
    /**
     * Run several page_act steps in one call (e.g. fill email, fill password, click submit). Returns a result per step and one diff at the end.
     *
     * `page.act_batch` (MCP: `page_act_batch`): toolset `core`, act, mutates the tab.
     */
    act_batch(args: PageActBatchArgs, options?: CallOptions): Promise<PageActBatchOutput>;
    /**
     * Accessibility tree of the page as an indented list of roles and names (debug preview; agents should use page_snapshot).
     *
     * `page.ax_tree` (MCP: `page_ax_tree`): toolset `hidden`, read.
     * Internal (hidden toolset): not listed to agents by default.
     */
    ax_tree(args?: PageAxTreeArgs, options?: CallOptions): Promise<PageAxTreeOutput>;
    /**
     * What changed on the page since a snapshot (default: the latest), in one line. Use it to watch for results that appear later (messages, loaded lists).
     *
     * `page.diff` (MCP: `page_diff`): toolset `core`, read.
     */
    diff(args?: PageDiffArgs, options?: CallOptions): Promise<PageDiffOutput>;
    /**
     * Search the whole page (also parts a snapshot collapsed) by role, name, text or regex. Returns matches with refs to use in page_act. Cheaper than a snapshot when you know what you need.
     *
     * `page.find` (MCP: `page_find`): toolset `core`, read.
     */
    find(args?: PageFindArgs, options?: CallOptions): Promise<PageFindOutput>;
    /**
     * Visible text of the page or of one element (ref), cut to max_chars. Use it to read articles, messages or table contents a snapshot only names.
     *
     * `page.read` (MCP: `page_read`): toolset `core`, read.
     */
    read(args?: PageReadArgs, options?: CallOptions): Promise<PageReadOutput>;
    /**
     * JPEG screenshot of the visible page, the full page or one element (ref). Costs many tokens: use only when page_snapshot/page_read are not enough (canvas, images, layout questions).
     *
     * `page.screenshot` (MCP: `page_screenshot`): toolset `core`, read.
     */
    screenshot(args?: PageScreenshotArgs, options?: CallOptions): Promise<PageScreenshotOutput>;
    /**
     * Compact text view of the page from the accessibility tree: one line per control with a ref (@S:eN) to act on, plus headings/landmarks. Use this instead of screenshots; after actions use the diff they return.
     *
     * `page.snapshot` (MCP: `page_snapshot`): toolset `core`, read.
     */
    snapshot(args?: PageSnapshotArgs, options?: CallOptions): Promise<PageSnapshotOutput>;
    /**
     * Visible text of the page (document.body.innerText), cut to `limit` characters.
     *
     * `page.text` (MCP: `page_text`): toolset `core`, read.
     */
    text(args?: PageTextArgs, options?: CallOptions): Promise<PageTextOutput>;
  };
  /** Commands `system.*`. */
  system: {
    /**
     * Check that BrowserMCP is running. Returns its name and version.
     *
     * `system.ping` (MCP: `system_ping`): toolset `core`, read.
     */
    ping(args?: SystemPingArgs, options?: CallOptions): Promise<SystemPingOutput>;
  };
  /** Commands `tabs.*`. */
  tabs: {
    /**
     * List open tabs (oldest first): id, title, url, loading.
     *
     * `tabs.list` (MCP: `tabs_list`): toolset `core`, read.
     */
    list(args?: TabsListArgs, options?: CallOptions): Promise<TabsListOutput>;
    /**
     * Open a URL in a new tab. Returns the new tab id.
     *
     * `tabs.open` (MCP: `tabs_open`): toolset `core`, act.
     */
    open(args: TabsOpenArgs, options?: CallOptions): Promise<TabsOpenOutput>;
  };
}

/** The typed `browser` object on top of any transport (WebSocket, HTTP, a mock…). */
export function createBrowser(transport: Transport): Browser {
  const call = <T>(name: string, args?: object, options?: CallOptions): Promise<T> =>
    transport.call(name, args ?? {}, options) as Promise<T>;
  return {
    call: ((name: string, args?: object, options?: CallOptions) =>
      call(name, args, options)) as Browser["call"],
    input: {
      keys: (args, options) => call<InputKeysOutput>("input.keys", args, options),
    },
    nav: {
      back: (args, options) => call<NavBackOutput>("nav.back", args, options),
      forward: (args, options) => call<NavForwardOutput>("nav.forward", args, options),
      goto: (args, options) => call<NavGotoOutput>("nav.goto", args, options),
      reload: (args, options) => call<NavReloadOutput>("nav.reload", args, options),
      wait: (args, options) => call<NavWaitOutput>("nav.wait", args, options),
    },
    page: {
      act: (args, options) => call<PageActOutput>("page.act", args, options),
      act_batch: (args, options) => call<PageActBatchOutput>("page.act_batch", args, options),
      ax_tree: (args, options) => call<PageAxTreeOutput>("page.ax_tree", args, options),
      diff: (args, options) => call<PageDiffOutput>("page.diff", args, options),
      find: (args, options) => call<PageFindOutput>("page.find", args, options),
      read: (args, options) => call<PageReadOutput>("page.read", args, options),
      screenshot: (args, options) => call<PageScreenshotOutput>("page.screenshot", args, options),
      snapshot: (args, options) => call<PageSnapshotOutput>("page.snapshot", args, options),
      text: (args, options) => call<PageTextOutput>("page.text", args, options),
    },
    system: {
      ping: (args, options) => call<SystemPingOutput>("system.ping", args, options),
    },
    tabs: {
      list: (args, options) => call<TabsListOutput>("tabs.list", args, options),
      open: (args, options) => call<TabsOpenOutput>("tabs.open", args, options),
    },
  };
}
